/* * <strings.h> for blarsdefs. * * blarslib shipped its own copy of this header, byte identical to * Microware's, so that copy is not here. Sources name it by absolute * path -- "/dd/blarsdefs/strings.h" -- which no -V can redirect, so this * stands in and reaches the real one. Nothing of Microware's is in * this file. * * The include is BY ABSOLUTE PATH deliberately: <strings.h> would find this * file again -- blarsdefs leads the search path -- and cpp would open * it until it ran out of paths (err=200). */#include "/dd/DEFS/strings.h"